package curryfarts.legacy;

import java.io.*;
import java.nio.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.function.*;

/** Java 8 parser and serial import runner. No supplied passwords or labels are retained. */
public final class TokenImportBatch {
    public static final int MAX_INPUT=1048576;
    public enum Kind { SESSION, REFRESH, INVALID }
    public enum Status { IMPORTED, DUPLICATE, INVALID, EXPIRED, FAILED }
    public enum Stored { IMPORTED, DUPLICATE, CANCELLED }
    public static final class Entry {public final int line;public final Kind kind;public final String token;Entry(int line,Kind kind,String token){this.line=line;this.kind=kind;this.token=token;}public String toString(){return "Entry[line="+line+", kind="+kind+"]";}}
    public static final class Result {public final int line;public final Status status;public final String message;Result(int line,Status status,String message){this.line=line;this.status=status;this.message=message;}}
    public static final class Progress {
        public final int total,processed,imported,duplicates,invalid,expired,failed;public final boolean cancelled;public final List<Result>results;
        Progress(int total,List<Result>results,boolean cancelled){this.total=total;this.results=Collections.unmodifiableList(new ArrayList<Result>(results));this.processed=results.size();this.cancelled=cancelled;int i=0,d=0,b=0,e=0,f=0;for(Result r:results){if(r.status==Status.IMPORTED)i++;else if(r.status==Status.DUPLICATE)d++;else if(r.status==Status.INVALID)b++;else if(r.status==Status.EXPIRED)e++;else f++;}imported=i;duplicates=d;invalid=b;expired=e;failed=f;}
    }
    public interface Sink {Stored store(TokenRefresher.Verified account,BooleanSupplier cancelled);}
    public interface Authenticator {TokenRefresher.Verified validate(String token)throws TokenRefresher.Failure,InterruptedException;TokenRefresher.Verified refresh(String token)throws TokenRefresher.Failure,InterruptedException;}
    public static Authenticator real(){final TokenRefresher r=new TokenRefresher();return new Authenticator(){public TokenRefresher.Verified validate(String t)throws TokenRefresher.Failure,InterruptedException{return r.validateSession(t);}public TokenRefresher.Verified refresh(String t)throws TokenRefresher.Failure,InterruptedException{return r.refresh(t);}};}
    public static List<Entry> parse(String input){if(input==null)input="";if(input.length()>MAX_INPUT)throw new IllegalArgumentException("Import at most 1 MiB.");List<Entry> entries=new ArrayList<Entry>();String[]lines=input.split("\\r\\n|\\r|\\n",-1);for(int i=0;i<lines.length;i++){String line=lines[i].trim();if(i==0&&line.startsWith("\uFEFF"))line=line.substring(1).trim();if(line.isEmpty()||line.startsWith("#")||line.startsWith("==="))continue;if(entries.size()>=1000)throw new IllegalArgumentException("Import at most 1,000 entries.");entries.add(parseLine(i+1,line));}return Collections.unmodifiableList(entries);}
    private static Entry parseLine(int number,String line){if(line.length()>32768)return new Entry(number,Kind.INVALID,"");String refresh=null,session=null;boolean fields=false;for(String part:line.split("\\|",-1)){int colon=part.indexOf(':');if(colon<0)continue;String name=part.substring(0,colon).trim();if(name.equalsIgnoreCase("REFRESHTOKEN")){fields=true;refresh=part.substring(colon+1).trim();}else if(name.equalsIgnoreCase("MCTOKEN")){fields=true;session=part.substring(colon+1).trim();}}
        if(fields){if(kind(refresh)==Kind.REFRESH)return new Entry(number,Kind.REFRESH,refresh);if(kind(session)==Kind.SESSION)return new Entry(number,Kind.SESSION,session);return new Entry(number,Kind.INVALID,"");}int colon=line.indexOf(':');String value=colon<0?line:line.substring(colon+1).trim();Kind kind=kind(value);return new Entry(number,kind,kind==Kind.INVALID?"":value);}
    private static Kind kind(String token){if(token==null||token.isEmpty()||token.length()>16384)return Kind.INVALID;for(int i=0;i<token.length();i++)if(token.charAt(i)<=32||token.charAt(i)>=127)return Kind.INVALID;String lower=token.toLowerCase(Locale.ROOT);if(lower.startsWith("m.c")||lower.contains("msaartifacts"))return Kind.REFRESH;if(token.startsWith("eyJ")&&token.matches("[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+"))return Kind.SESSION;return Kind.INVALID;}
    public static String readFile(Path path)throws IOException {if(path==null||path.getFileName()==null||!path.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".txt")||!Files.isRegularFile(path))throw new IOException("Choose a regular UTF-8 TXT file.");ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream in=Files.newInputStream(path)){byte[]buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("File read cancelled.");if(n>MAX_INPUT-data.size())throw new IOException("File exceeds 1 MiB.");data.write(buffer,0,n);}}try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(data.toByteArray())).toString();}catch(CharacterCodingException e){throw new IOException("Use UTF-8 text.");}}
    public static Progress run(String text,Authenticator auth,Sink sink,BooleanSupplier cancelled,Consumer<Progress> progress){List<Entry>entries=parse(text);List<Result>results=new ArrayList<Result>();Set<String>seen=new HashSet<String>();long lastRefresh=0;boolean stopped=false;progress.accept(new Progress(entries.size(),results,false));for(Entry entry:entries){if(cancelled(cancelled)){stopped=true;break;}Status status;String message;boolean rateLimited=false;if(entry.kind==Kind.INVALID){status=Status.INVALID;message="Expected a session or Microsoft refresh token.";}else if(seen.contains(fingerprint(entry.token))){status=Status.DUPLICATE;message="Token already checked in this batch.";}else try{TokenRefresher.Verified account;if(entry.kind==Kind.REFRESH){long wait=4000-(System.currentTimeMillis()-lastRefresh);if(lastRefresh!=0&&wait>0)Thread.sleep(wait);if(cancelled(cancelled)){stopped=true;break;}lastRefresh=System.currentTimeMillis();account=auth.refresh(entry.token);}else account=auth.validate(entry.token);if(cancelled(cancelled)){stopped=true;break;}Stored saved=sink.store(account,()->cancelled(cancelled));if(saved==Stored.CANCELLED){stopped=true;break;}seen.add(fingerprint(entry.token));status=saved==Stored.IMPORTED?Status.IMPORTED:Status.DUPLICATE;message=saved==Stored.IMPORTED?"Imported "+account.username+".":"Saved account updated; duplicate skipped.";}catch(InterruptedException e){Thread.currentThread().interrupt();stopped=true;break;}catch(TokenRefresher.Failure e){status=e.kind==TokenRefresher.FailureKind.EXPIRED?Status.EXPIRED:e.kind==TokenRefresher.FailureKind.INVALID||e.kind==TokenRefresher.FailureKind.UNSUPPORTED?Status.INVALID:Status.FAILED;message=e.getMessage();rateLimited=e.kind==TokenRefresher.FailureKind.RATE_LIMITED;}catch(RuntimeException e){status=Status.FAILED;message="Could not save this account. Retry later.";}results.add(new Result(entry.line,status,message));progress.accept(new Progress(entries.size(),results,false));if(rateLimited)break;}Progress end=new Progress(entries.size(),results,stopped||cancelled(cancelled));progress.accept(end);return end;}
    private static boolean cancelled(BooleanSupplier flag){return Thread.currentThread().isInterrupted()||flag.getAsBoolean();}
    private static String fingerprint(String value){try{return Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException impossible){throw new AssertionError();}}
    private TokenImportBatch(){}
}
